#!/usr/bin/env python3
# Generated by runa via A2A Mesh delegation
"""
A2A Mesh — Üzenetprioritás-címkék (P0–P2)
Sürgős/szavazás jellegű üzenetek ne fulladjanak a laza csevegésbe.

Prioritási szintek:
  P0 — Kritikus / sürgős (szavazás, döntés, rendszer-üzenet)
  P1 — Fontos (irányított kérdés, feladat-delegálás)
  P2 — Normál / laza csevegés (alapértelmezett)

A modul tartalmaz:
  - Priority enum
  - PriorityTag adatosztály
  - PriorityMessage adatosztály (telles mesh-üzenet burkoló)
  - PriorityQueue (prioritás szerint rendezett várakozási sor)
  - MessageRouter (útválasztó, ami P0 üzeneteket azonnal kiszolgálja)
  - CLI demo a repó gyökeréből futtatható
"""

from __future__ import annotations

import json
import time
import uuid
import heapq
from dataclasses import dataclass, field, asdict
from enum import IntEnum
from typing import Any, Optional


# ---------------------------------------------------------------------------
# Prioritás definíciók
# ---------------------------------------------------------------------------

class Priority(IntEnum):
    """Üzenet prioritási szintek — alacsonyabb szám = magasabb prioritás."""
    P0 = 0  # kritikus / sürgős / szavazás
    P1 = 1  # fontos / irányított
    P2 = 2  # normál / laza csevegés

    @property
    def label(self) -> str:
        return self.name

    @classmethod
    def from_string(cls, value: str) -> "Priority":
        value = value.strip().upper()
        if value not in ("P0", "P1", "P2"):
            raise ValueError(f"Érvénytelen prioritás: {value} (P0/P1/P2)")
        return cls[value]

    @classmethod
    def from_int(cls, value: int) -> "Priority":
        if value not in (0, 1, 2):
            raise ValueError(f"Érvénytelen prioritás-kód: {value}")
        return cls(value)


@dataclass
class PriorityTag:
    """Egy üzenethez rendelt prioritás-címke metaadatokkal."""
    priority: Priority
    reason: str = ""               # miért kapta ezt a prioritást
    expires_at: Optional[float] = None  # unix timestamp; None = nem jár le
    auto_detected: bool = False    # heurisztika alapján automatikus?

    def is_expired(self, now: Optional[float] = None) -> bool:
        if self.expires_at is None:
            return False
        now = now if now is not None else time.time()
        return now >= self.expires_at

    def to_dict(self) -> dict[str, Any]:
        d = asdict(self)
        d["priority"] = self.priority.label
        return d

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> "PriorityTag":
        return cls(
            priority=Priority.from_string(d["priority"]),
            reason=d.get("reason", ""),
            expires_at=d.get("expires_at"),
            auto_detected=d.get("auto_detected", False),
        )


# ---------------------------------------------------------------------------
# Üzenet modell
# ---------------------------------------------------------------------------

@dataclass
class PriorityMessage:
    """Mesh üzenet prioritás-címkével."""
    id: str
    sender: str
    content: str
    tag: PriorityTag
    timestamp: float = field(default_factory=time.time)
    topic: str = "general"
    metadata: dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> dict[str, Any]:
        return {
            "id": self.id,
            "sender": self.sender,
            "content": self.content,
            "tag": self.tag.to_dict(),
            "timestamp": self.timestamp,
            "topic": self.topic,
            "metadata": self.metadata,
        }

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> "PriorityMessage":
        return cls(
            id=d["id"],
            sender=d["sender"],
            content=d["content"],
            tag=PriorityTag.from_dict(d["tag"]),
            timestamp=d.get("timestamp", time.time()),
            topic=d.get("topic", "general"),
            metadata=d.get("metadata", {}),
        )

    def to_json(self) -> str:
        return json.dumps(self.to_dict(), ensure_ascii=False)


# ---------------------------------------------------------------------------
# Heurisztikus prioritás-detektálás
# ---------------------------------------------------------------------------

# Kulcsszavak, amik P0-t indokolnak
_P0_KEYWORDS = [
    "szavazás", "szavazas", "döntés", "dontes", "sürgős", "surgos",
    "kritikus", "azonnal", "vész", "vesz", "alert", "vote", "urgent",
    "critical", "asap", "p0", "deadline", "határidő",
]

# Kulcsszavak, amik P1-et indokolnak
_P1_KEYWORDS = [
    "kérdés", "kerdes", "?", "feladat", "delegál", "delegálás",
    "kérlek", "help", "question", "task", "assign", "please",
    "fontos", "important",
]


def detect_priority(content: str) -> PriorityTag:
    """
    Heurisztikus prioritás-detektálás szöveg alapján.
    Visszatér egy PriorityTag-gel, ahol auto_detected=True.
    """
    lower = content.lower()
    for kw in _P0_KEYWORDS:
        if kw in lower:
            return PriorityTag(
                priority=Priority.P0,
                reason=f"automatikus: kulcsszó '{kw}'",
                auto_detected=True,
            )
    for kw in _P1_KEYWORDS:
        if kw in lower:
            return PriorityTag(
                priority=Priority.P1,
                reason=f"automatikus: kulcsszó '{kw}'",
                auto_detected=True,
            )
    return PriorityTag(
        priority=Priority.P2,
        reason="automatikus: alapértelmezett",
        auto_detected=True,
    )


# ---------------------------------------------------------------------------
# Prioritásos várakozási sor
# ---------------------------------------------------------------------------

class PriorityQueue:
    """
    Min-heap alapú prioritásos sor.
    P0 üzenetek előbb kerülnek kiszolgálásra, mint P1/P2.
    Azonos prioritáson belül FIFO sorrend.
    """

    def __init__(self) -> None:
        self._heap: list[tuple[int, int, PriorityMessage]] = []
        self._counter = 0  # FIFO tie-breaker
        self._index: dict[str, PriorityMessage] = {}

    def push(self, msg: PriorityMessage) -> None:
        if msg.id in self._index:
            raise ValueError(f"Duplikált üzenet ID: {msg.id}")
        priority_val = int(msg.tag.priority)
        self._counter += 1
        heapq.heappush(self._heap, (priority_val, self._counter, msg))
        self._index[msg.id] = msg

    def pop(self) -> Optional[PriorityMessage]:
        while self._heap:
            _, _, msg = heapq.heappop(self._heap)
            # lejárt üzenetek kihagyása
            if msg.tag.is_expired():
                self._index.pop(msg.id, None)
                continue
            self._index.pop(msg.id, None)
            return msg
        return None

    def peek(self) -> Optional[PriorityMessage]:
        while self._heap:
            _, _, msg = self._heap[0]
            if msg.tag.is_expired():
                heapq.heappop(self._heap)
                self._index.pop(msg.id, None)
                continue
            return msg
        return None

    def __len__(self) -> int:
        return len(self._heap)

    def stats(self) -> dict[str, int]:
        counts = {"P0": 0, "P1": 0, "P2": 0}
        for _, _, msg in self._heap:
            counts[msg.tag.priority.label] += 1
        counts["total"] = len(self._heap)
        return counts

    def drain_by_priority(self, priority: Priority) -> list[PriorityMessage]:
        """Kiveszi és visszaadja az összes adott prioritású üzenetet."""
        result = []
        remaining = []
        while self._heap:
            _, seq, msg = heapq.heappop(self._heap)
            if msg.tag.priority == priority and not msg.tag.is_expired():
                result.append(msg)
                self._index.pop(msg.id, None)
            else:
                remaining.append((int(msg.tag.priority), seq, msg))
        self._heap = remaining
        heapq.heapify(self._heap)
        return result


# ---------------------------------------------------------------------------
# Üzenet-router
# ---------------------------------------------------------------------------

class MessageRouter:
    """
    Fogadja a bejövő üzeneteket, prioritás szerint sorba rendezi,
    és kiszolgálja őket — P0 előbb.
    """

    def __init__(self, node_id: str) -> None:
        self.node_id = node_id
        self.queue = PriorityQueue()
        self.delivered: list[PriorityMessage] = []
        self._auto_detect = True

    def enable_auto_detect(self, enabled: bool = True) -> None:
        self._auto_detect = enabled

    def send(
        self,
        sender: str,
        content: str,
        priority: Optional[Priority] = None,
        reason: str = "",
        topic: str = "general",
        ttl_seconds: Optional[float] = None,
        metadata: Optional[dict[str, Any]] = None,
    ) -> PriorityMessage:
        """
        Új üzenet létrehozása és betevése a sorba.
        Ha priority=None és auto_detect be van kapcsolva, heurisztikát használ.
        """
        if priority is not None:
            tag = PriorityTag(
                priority=priority,
                reason=reason or "manuálisan megadva",
                auto_detected=False,
                expires_at=(time.time() + ttl_seconds) if ttl_seconds else None,
            )
        elif self._auto_detect:
            tag = detect_priority(content)
            if ttl_seconds:
                tag.expires_at = time.time() + ttl_seconds
        else:
            tag = PriorityTag(
                priority=Priority.P2,
                reason="alapértelmezett",
                expires_at=(time.time() + ttl_seconds) if ttl_seconds else None,
            )

        msg = PriorityMessage(
            id=str(uuid.uuid4()),
            sender=sender,
            content=content,
            tag=tag,
            topic=topic,
            metadata=metadata or {},
        )
        self.queue.push(msg)
        return msg

    def deliver_next(self) -> Optional[PriorityMessage]:
        """Kiszolgálja a legmagasabb prioritású üzenetet."""
        msg = self.queue.pop()
        if msg:
            self.delivered.append(msg)
        return msg

    def deliver_all(self) -> list[PriorityMessage]:
        """Kiszolgálja az összes üzenetet prioritás sorrendben."""
        results = []
        while True:
            msg = self.deliver_next()
            if msg is None:
                break
            results.append(msg)
        return results

    def deliver_priority(self, priority: Priority) -> list[PriorityMessage]:
        """Csak egy adott prioritású üzeneteket szolgáltatja ki."""
        msgs = self.queue.drain_by_priority(priority)
        self.delivered.extend(msgs)
        return msgs

    def pending_stats(self) -> dict[str, int]:
        return self.queue.stats()

    def summary(self) -> str:
        s = self.queue.stats()
        return (
            f"[{self.node_id}] Várakozó: {s['total']} "
            f"(P0:{s['P0']} P1:{s['P1']} P2:{s['P2']})  "
            f"Kézbesített: {len(self.delivered)}"
        )


# ---------------------------------------------------------------------------
# Szavazás-segéd: P0 szavazási üzenet gyártó
# ---------------------------------------------------------------------------

def create_vote_message(
    sender: str,
    question: str,
    options: list[str],
    deadline_seconds: float = 300.0,
    topic: str = "vote",
) -> PriorityMessage:
    """
    Létrehoz egy P0 prioritású szavazási üzenetet TTL-vel.
    A szavazás lejárta után az üzenet automatikusan eldobódik a sorból.
    """
    content = f"[SZAVAZÁS] {question} | Opciók: {', '.join(options)}"
    tag = PriorityTag(
        priority=Priority.P0,
        reason="szavazás — sürgős döntés",
        expires_at=time.time() + deadline_seconds,
        auto_detected=False,
    )
    return PriorityMessage(
        id=str(uuid.uuid4()),
        sender=sender,
        content=content,
        tag=tag,
        topic=topic,
        metadata={
            "type": "vote",
            "question": question,
            "options": options,
            "deadline_seconds": deadline_seconds,
        },
    )


# ---------------------------------------------------------------------------
# CLI Demo
# ---------------------------------------------------------------------------

def _print_msg(msg: PriorityMessage, index: int) -> None:
    print(f"  {index}. [{msg.tag.priority.label}] "
          f"<{msg.sender}> ({msg.topic}) {msg.content}")
    if msg.tag.reason:
        print(f"     ↳ ok: {msg.tag.reason}"
              f"{' (auto)' if msg.tag.auto_detected else ''}")
    if msg.tag.expires_at:
        remaining = msg.tag.expires_at - time.time()
        print(f"     ↳ lejár: {remaining:.1f}s múlva")


def main() -> None:
    print("=" * 70)
    print("A2A Mesh — Üzenetprioritás-címkék (P0–P2) demo")
    print("Generated by runa via A2A Mesh delegation")
    print("=" * 70)

    router = MessageRouter(node_id="runa-node")

    # --- Laza csevegés (P2) ---
    print("\n› Laza csevegés beküldése (P2 várható)...")
    router.send("alice", "Szia! Hogy vagy ma?")
    router.send("bob", "Valaki látta a tegnap esti meccset?")
    router.send("carol", "Ja, egész jó volt a második félidő.")

    # --- Fontos üzenet (P1) — kérdés jellegű ---
    print("› Irányított kérdés beküldése (P1 várható)...")
    router.send("dave", "Kérlek segíts: hogyan regisztrálok új node-ot?")

    # --- Sürgős szavazás (P0) — manuálisan + TTL ---
    print("› Sürgős szavazás beküldése (P0, TTL=60s)...")
    vote_msg = create_vote_message(
        sender="runa",
        question="Engedélyezzük a store-and-forward üzeneteket?",
        options=["igen", "nem", "tartózkodik"],
        deadline_seconds=60.0,
    )
    router.queue.push(vote_msg)

    # --- Még egy P0 automatikus detektálással ---
    print("› Sürgős üzenet kulcsszó-alapú detektálással...")
    router.send("eve", "Ez sürgős: a mesh router leállt, azonnal nézzétek!")

    # --- Statisztika ---
    print("\n" + "─" * 70)
    print(router.summary())
    print("─" * 70)

    # --- Kiszolgálás prioritás sorrendben ---
    print("\n› Üzenetek kiszolgálása prioritás sorrendben:\n")
    delivered = router.deliver_all()
    for i, msg in enumerate(delivered, 1):
        _print_msg(msg, i)

    print(f"\n› Összesen {len(delivered)} üzenet kézbesítve.")
    print(router.summary())

    # --- JSON szerializáció bemutatása ---
    print("\n› Példa üzenet JSON reprezentációja:")
    sample = create_vote_message(
        sender="runa",
        question="Prioritás-címkék bevezetése?",
        options=["elfogad", "elutasít"],
        deadline_seconds=120.0,
    )
    print(json.dumps(sample.to_dict(), indent=2, ensure_ascii=False))

    # --- PriorityQueue közvetlen teszt ---
    print("\n› PriorityQueue egységteszt...")
    pq = PriorityQueue()
    pq.push(PriorityMessage("m1", "x", "laza", PriorityTag(Priority.P2)))
    pq.push(PriorityMessage("m2", "y", "sürgős", PriorityTag(Priority.P0)))
    pq.push(PriorityMessage("m3", "z", "fontos kérdés", PriorityTag(Priority.P1)))
    order = []
    while len(pq) > 0:
        m = pq.pop()
        order.append(m.tag.priority.label if m else "None")
    assert order == ["P0", "P1", "P2"], f"Várva P0,P1,P2 — kapott: {order}"
    print(f"  Sorrend: {order}  ✓")

    print("\n✓ Demo sikeresen lefutott.")


if __name__ == "__main__":
    main()